SELECT 'TXT_KEY_CITYSTATE_CLERMONT', 					'클레르몽' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CLERMONT_ADJ', 					'클레르몽의' UNION ALL
SELECT 'TXT_KEY_CIV5_CLERMONT_TEXT', 						'클레르몽은 기독교계가 이슬람의 지배로부터 예루살렘을 해방시키려 했던 제1차 십자군 원정의 출발점이었습니다. 교황 우르바노 2세는 1095년 제2차 클레르몽 공의회에서 십자군을 설교했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS', 					'테구시갈파' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS_ADJ', 					'온두라스의' UNION ALL
SELECT 'TXT_KEY_CIV5_HONDURAS_TEXT', 						'온두라스는 16세기 스페인이 점령하기 전까지 여러 메소아메리카 문화의 본거지였습니다. 온두라스는 1821년에 독립하여 공화국이 되었습니다. 그러나 이 공화국은 정부가 외국 투자자들의 개발을 장려하고 그 결과 바나나 생산이 주가 되는 바나나 공화국의 전형으로 남아있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AUCKLAND', 					'파리하카' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AUCKLAND_ADJ', 					'마오리의' UNION ALL
SELECT 'TXT_KEY_CIV5_AUCKLAND_TEXT', 						'마오리족이 현재 뉴질랜드 북부의 지협에 정착했을 때, 그들은 주변 풍경이 비옥한 땅, 무성한 정글, 휴화산으로 가득 차 있는 것을 발견했습니다. 지협 양쪽의 보호된 천연 항구는 풍부한 어업 자원과 전쟁 카누("와카 타우아")의 기지를 제공했습니다. 정착민들은 이곳을 "타마키 마카우라우"라고 명명했는데, 대략 "백 명의 연인이 찾는 처녀"라는 뜻입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ARMAGH', 						'아마' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ARMAGH_ADJ', 						'아마의' UNION ALL
SELECT 'TXT_KEY_CIV5_ARMAGH_TEXT', 							'아일랜드의 도시 아마는 오랫동안 종교와 함께해 왔습니다. 고대 이교도들의 숭배 장소로 여겨지던 이곳은 5세기에 기독교 선교사 성 패트릭이 언덕 정상에 석조 교회를 짓고 축성하면서 명성을 얻었습니다. 그 주변으로 수도원이 생겨났고, 아일랜드 전역에 기독교를 전파하는 데 헌신하는 마을, 즉 신학의 교두보가 되었습니다.[NEWLINE][NEWLINE]그렇다고 아마가 해안 도시는 아닙니다. 북아일랜드에 위치한 이곳은 바다까지 25마일 정도 떨어져 있습니다. 그럼에도 불구하고 아일랜드 교회의 본산이라는 명성 때문에 부를 노리는 자들의 매력적인 표적이 되었습니다. 바이킹은 9세기에 두 번이나 아마의 수도원을 습격했고, 매번 육로를 통해 종교 유물을 한가득 약탈해 갔습니다. 침략한 노르만 기사 존 드 코시는 12세기 후반에 마을을 약탈하며 그 전통을 반복하려 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT', 						'무스카트' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT_ADJ', 						'무스카트의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUSCAT_TEXT', 							'무스카트를 흐르는 무역은 적어도 2천 년 동안 이 도시의 생명선이었습니다. 알하자르 산맥 기슭에 자리 잡은 이곳을 프톨레마이오스는 1세기에 이미 숨겨진 항구("Cryptus Portus")라고 불렀습니다. 불행히도 이 도시는 충분히 숨겨지지 않았습니다. 페르시아만 입구라는 최적의 위치 때문에 오랫동안 정복의 매력적인 표적이 되었습니다.[NEWLINE][NEWLINE]수 세기 동안 무스카트 항구에는 사산조, 아라비아(7세기에 이슬람으로 개종), 아바스, 셀주크, 페르시아 등 수많은 깃발이 휘날렸습니다. 16세기 초, 포르투갈 제독은 대포로 무역 관계를 열고자 했고 무스카트 대부분을 불태웠습니다. 도시는 재건되었고 1650년 오만인이 그들을 몰아내고 항구 도시를 되찾을 때까지 포르투갈의 지배하에 있었습니다.[NEWLINE][NEWLINE]무스카트는 오랫동안 오만 내륙 부족들과 갈등을 빚어왔으며, 가장 흔한 원인은 자치권 문제였습니다. 18세기 이러한 혼란기 속에 알 부 사이드 왕조가 일어났고, 현대까지 이어지고 있습니다. 오늘날 광범위하게 현대화된 무스카트는 오만의 수도이자 중요한 무역항으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA', 					'그라나다' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA_ADJ', 					'그라나다의' UNION ALL
SELECT 'TXT_KEY_CIV5_GRANADA_TEXT', 						'8세기에 우마이야 칼리프조는 이베리아반도로 확산되어 서고트 히스파니아를 빠르게 정복했습니다. 현재 스페인 남부의 요새화된 정착지였던 그라나다도 침략에 휩쓸렸습니다. 훗날(정확히는 15세기 후반) 가톨릭 군주들에게 항복함으로써 안달루시아의 레콘키스타는 끝났지만, 750년 동안 그라나다는 무어인의 것이었습니다.[NEWLINE][NEWLINE]시에라 네바다 산맥 기슭에 위치한 그라나다는 저지대 평원에 위치하여 방어가 거의 불가능하다는 불운을 안고 있었습니다. 무어인 통치자들은 이를 빠르게 깨닫고 마을이 내려다보이는 방어하기 좋은 산기슭으로 권력의 중심을 옮겼습니다. 그들의 계획 중 일부는 알카사르 건설을 포함했고, 그중 하나는 훗날 아름다운 알람브라 궁전으로 개조되었습니다.[NEWLINE][NEWLINE]그라나다의 무어인 주인들은 수 세기에 걸쳐 바뀌었습니다. 알모하드 왕조가 알모라비드 왕조를 대체했고, 알모라비드 왕조는 우마이야 왕조의 잔재를 계승했습니다. 13세기 나스르 왕조가 가톨릭 카스티야 왕국과 동맹을 맺으면서 그라나다 토후국이 탄생했고 도시의 운명은 다시 바뀌었습니다. 사하라 이남 아프리카의 무역 중심지에 직접 접근할 수 있었던 덕분에 그라나다는 한동안 레콘키스타로부터 자유를 살 수 있었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL', 					'렐루' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL_ADJ', 					'렐루의' UNION ALL
SELECT 'TXT_KEY_CIV5_NAN_MADOL_TEXT', 						'렐루는 주요 선사 및 역사 고고학 유적지입니다. 유적은 14세기와 15세기에 정점에 달했던 문명의 흔적이며, 19세기 초 유럽인과 접촉할 당시에도 그 요소들이 여전히 눈에 띄었습니다. 렐루의 통치자들은 점차 코스라에 섬을 정복하고 통일했습니다. 그들은 수도 렐루에서 고고학자들이 통가나 하와이 왕국과 유사하다고 믿는 군주제로 섬을 통치했습니다.[NEWLINE][NEWLINE]대부분의 고고학자와 역사학자들은 미크로네시아 폰페이섬 동쪽 해안에 인접한 버려진 도시 난마돌의 폐허가 잃어버린 대륙 무의 잔재라고 믿지 않습니다. 대신 이 도시는 석호 안에 건설되었으며, 돌과 산호로 채운 플랫폼 위에 지어진 약 100개의 작은 인공 섬들로 구성되어 있고 조수 운하로 분리되어 있습니다. 선사 시대 대륙 침몰의 잔재라기보다는, 서기 8세기경 인공 섬 건설이 시작되었고 12세기와 13세기에 거석 구조물 건설이 이루어졌다는 것이 가장 유력한 추측입니다. 이 모든 것은 사우델레우르 왕조의 엘리트 계급이 평민들과 섞이지 않기 위함이었습니다.[NEWLINE][NEWLINE]석호 도시의 원래 이름은 소운 난렝("천국의 암초")이었으며, 유럽 탐험가들은 이를 "태평양의 베니스"라고 불렀습니다. 이름이 붙여진 대부분의 섬은 추장과 사제들의 거주지였지만... 일부는 특별한 용도로 사용되었습니다. 페이네링에서는 식량 준비와 코코넛 오일 생산, 다파후에서는 카누 건조가 이루어졌습니다. 영안실 "구역"에는 무덤으로 덮인 약 58개의 섬이 포함되어 있습니다. 난마돌은 폰페이와 템웬 섬의 씨족(총 2만 5천 명)을 통합하는 데 성공한 사우델레우르 왕조의 정치, 종교, 문화적 중심지였습니다. 그 직후 통치자는 부족 추장들을 감시할 수 있는 새로운 도시로 강제 이주 시켰습니다.[NEWLINE][NEWLINE]전성기 난마돌의 인구는 약 1,000명 정도였을 것입니다. 섬에는 식량이나 담수가 없었기 때문에 모든 것을 폰페이에서 배로 실어 날라야 했습니다. 전설에 따르면 모든 건물과 무덤에 사용된 돌은 사우델레우르 왕조를 세운 쌍둥이 마법사 올리시파와 올로소파가 섬으로 날려 보냈다고 합니다. 창조의 사실이 무엇이든, 1800년대 초 유럽인들이 도착했을 때 난마돌은 이미 버려진 상태였으며, 아마도 1450년경 사우델레우르 왕조가 붕괴했을 때 버려졌을 것입니다.' UNION ALL
