SELECT 'TXT_KEY_CITYSTATE_GWYNEDD_ADJ', 					'웨일스의' UNION ALL
SELECT 'TXT_KEY_CIV5_GWYNEDD_TEXT', 						'귀네드는 로마 시대 말기부터 13세기 잉글랜드에 정복될 때까지 독립적인 웨일스 왕국이었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA', 						'수아목스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA_ADJ', 						'무이스카의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUISCA_TEXT', 							'무이스카는 16세기 스페인 정복자들이 파괴하기 전까지 서쪽의 판체, 북서쪽의 무조, 북쪽의 과네, 북동쪽의 라체, 동쪽의 아차과, 남쪽의 수타가오 등 여러 안데스 문화의 본거지였습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LACONIA', 					'스파르타' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LACONIA_ADJ', 					'스파르타의' UNION ALL
SELECT 'TXT_KEY_CIV5_LACONIA_TEXT', 						'도시 국가 수도인 스파르타의 지역으로 간주되는 라코니아는 펠로폰네소스 지역의 패권을 다투는 가장 강력한 지역 세력 중 하나가 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK', 						'체박' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK_ADJ', 						'체박의' UNION ALL
SELECT 'TXT_KEY_CIV5_CHEVAK_TEXT', 							'체박 원주민들의 고향인 알래스카의 한 지역입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO', 				'산토도밍고' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO_ADJ', 				'도미니카의' UNION ALL
SELECT 'TXT_KEY_CIV5_SANTO_DOMINGO_TEXT', 					'산토도밍고는 아메리카 대륙에서 가장 오래된 유럽 도시가 되었습니다. 원래 라 누에바 이사벨라라는 이름이었으나 1495년 성 도미니코를 기리기 위해 ''산토도밍고''로 개명되었습니다. 산토도밍고는 도시가 커지고 번영함에 따라 ''카리브해의 관문''으로 알려지게 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA', 					'마나과' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA_ADJ', 					'마나과의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANAGUA_TEXT', 						'스페인계 메스티소와 백인으로 구성된 마나과는 어촌 마을에서 번영하는 스페인 도시로, 그리고 현재는 중앙아메리카에서 가장 잘 알려진 선진 도시로 발전했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ODENSO', 						'헬싱키' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ODENSO_ADJ', 						'핀란드의' UNION ALL
SELECT 'TXT_KEY_CIV5_ODENSO_TEXT', 							'문자 그대로 오딘의 섬으로 번역되는 이곳은 핀란드 왕국이 북유럽 신화의 신 오딘을 기리기 위해 명명했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG', 					'양성' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG_ADJ', 					'양성의' UNION ALL
SELECT 'TXT_KEY_CIV5_YANGCHENG_TEXT', 						'하나라의 첫 번째 수도로 여겨지는 이곳은 잉강 위에 지어졌으며 왕조가 멸망할 때까지 유지되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS', 					'파노테우스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS_ADJ', 					'포키스의' UNION ALL
SELECT 'TXT_KEY_CIV5_PHANOTEUS_TEXT', 						'파노테우스는 매우 오래된 마을로, 원래 플레기아인들이 거주했습니다. 프로메테우스가 이곳에서 인류를 만들었다고 믿어집니다. 크세르크세스 휘하의 페르시아인, 필리포스 2세 휘하의 마케도니아인, 폼페이우스 대왕 휘하의 로마인들에 의해 시간이 흐르면서 파괴되고 손상될 때까지 유지되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA', 						'두알라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA_ADJ', 						'두알라의' UNION ALL
