SELECT 'TXT_KEY_CIV5_KIGALI_TEXT', 							'키갈리는 르완다의 수도로 14세기 르완다 왕국에 의해 처음 개발되었으며, 현대에 이르러 역사적인 수도가 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA', 						'레부카' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA_ADJ', 						'피지의' UNION ALL
SELECT 'TXT_KEY_CIV5_LEVUKA_TEXT', 							'레부카는 남태평양 국가 피지의 오발라우섬 동해안에 있는 항구 도시이자 로마이비티주의 주도입니다. 1822년 미국 모험가가 정착한 이 지역은 미국 남북 전쟁(1861-65) 중 세계 목화 공급이 중단되었을 때 목화 붐의 중심지였습니다.[NEWLINE][NEWLINE]1871년 피지 최초의 근대 민족 국가인 피지 왕국이 건국되었을 때 세루 에페니사 카코바우가 레부카에서 왕으로 즉위했습니다. 1874년 피지가 영국의 식민지로 합병된 후 레부카는 1877년 행정부가 수바로 이전될 때까지 수도로 남아 있었지만, 공식적인 이전은 1882년에야 이루어졌습니다.[NEWLINE][NEWLINE]현재는 주로 일본, 한국, 대만 어선이 공급하는 피지 참치 가공 산업의 중심지입니다. 이 마을의 19세기 건축물은 여전히 대부분 온전하며, 2013년 레부카는 문화적, 역사적 가치를 인정받아 유네스코 세계문화유산으로 지정되었습니다.' UNION ALL
