SELECT 'TXT_KEY_CIV5_SURREY_TEXT', 							'서리는 영국 남동부에 있는 카운티입니다. 비행장으로 처음 사용된 것으로 알려진 이 카운티는 비행기 생산과 항공 테스트에 중요한 역할을 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN', 						'타이베이' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN_ADJ', 						'타이베이의' UNION ALL
SELECT 'TXT_KEY_CIV5_TAIWAN_TEXT', 							'타이베이는 중화민국의 수도이며 대만의 문화, 정치, 경제 중심지를 형성합니다. 국민당의 중국 망명 정부가 수립되기 전 타이베이는 중국, 일본, 필리핀 사이의 무역로에 위치한 작은 지방 수도였습니다. 주변 지역의 대부분은 여전히 여러 포르모사 원주민 그룹이 거주하고 있어 한족의 지배를 받는 중국 본토와는 구별되는 풍부한 문화적 구조를 만들고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO', 						'옥에오' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO_ADJ', 						'푸난의' UNION ALL
SELECT 'TXT_KEY_CIV5_OC_EO_TEXT', 							'푸난은 서기 1세기에 캄보디아에서 발생하여 6세기에 첸라 국가에 통합된 고대 국가입니다. 푸난(아마도 "산"을 뜻하는 프놈의 중국어 음차)은 동남아시아 최초의 중요한 힌두교 왕국이었습니다. 현재의 베트남, 태국, 캄보디아 일부를 포함했습니다. 푸난은 인도 및 중국과 무역 관계를 맺었으며, 3세기에서 6세기 사이에 중국 황제에게 조공을 바쳤습니다.[NEWLINE][NEWLINE]푸난은 3세기 왕 판시만(스레이 메아라라고도 함) 치하에서 권력의 정점에 도달했습니다. 판시만은 제국의 해군을 확장하고 푸난 관료제를 개선하여, 특히 제국의 먼 지역에서 지역 관습과 정체성을 대부분 온전하게 유지하는 준봉건적 패턴을 만들었습니다. 판시만과 그의 후계자들은 또한 해상 무역을 규제하기 위해 중국과 인도에 사절을 보냈습니다. 왕국은 동남아시아의 인도화 과정을 가속화했을 가능성이 큽니다. 첸라와 같은 후기 동남아시아 왕국들은 푸난 궁정을 모방했을 수 있습니다. 푸난인들은 이 지역 제국들의 패턴이 될 강력한 중상주의와 상업 독점 시스템을 구축했습니다.[NEWLINE][NEWLINE]푸난의 해상 무역 의존은 푸난 몰락의 시작 원인으로 간주됩니다. 그들의 해안 항구는 외국 지역과의 무역을 허용하여 상품을 북쪽과 해안 인구에게 전달했습니다. 그러나 해상 무역이 수마트라로 이동하고, 스리비자야 무역 제국이 부상하고, 중국이 동남아시아 전역의 무역로를 장악하면서 남부의 경제적 불안정이 초래되었고 정치와 경제가 북쪽으로 이동하게 되었습니다. 푸난은 6세기에 첸라 왕국의 크메르 정치체에 의해 대체되고 흡수되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU', 					'팀푸' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU_ADJ', 					'팀푸의' UNION ALL
SELECT 'TXT_KEY_CIV5_THIMPHU_TEXT', 						'1955년부터 팀푸는 히말라야 동쪽 끝에 있는 남아시아의 내륙국 부탄 왕국의 수도입니다. 북쪽으로는 티베트(중국), 남쪽, 동쪽, 서쪽으로는 인도와 국경을 접하고 있습니다. 부탄은 17세기 초까지 작은 전쟁 영지들의 집합체로 존재했습니다. 당시 티베트의 종교적 박해를 피해 도망친 라마이자 군사 지도자인 나왕 남걀(초대 샤브드룽 린포체)이 이 지역을 통일하고 독특한 부탄의 정체성을 배양했습니다. 20세기 초 부탄은 대영제국과 접촉했고 독립 후 인도와 강력한 양자 관계를 유지했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA', 					'안도라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA_ADJ', 					'안도라의' UNION ALL
SELECT 'TXT_KEY_CIV5_ANDORRA_TEXT', 						'피레네산맥 남쪽 경사면에 위치한 안도라 공국은 발리라강을 형성하는 계곡들의 집합체로 구성되어 있습니다. 안도라의 독립은 전통적으로 서기 803년 이슬람교도들로부터 이 지역을 되찾은 샤를마뉴 대제 덕분이라고 합니다. 1278년 프랑스 푸아 백작과 스페인 우르젤 주교의 공동 주권하에 놓였으며, 이후 스페인 우르젤 주교와 프랑스 국가 원수가 공동으로 통치했습니다. 유럽의 마지막 봉건 통치 시스템인 이 제도는 1993년 보통 선거로 선출된 안도라 의회에 공동 영주의 권한 대부분을 이양하는 헌법이 채택될 때까지 계속되었습니다.[NEWLINE][NEWLINE]안도라는 오랫동안 카탈루냐와 강한 친밀감을 유지해 왔습니다. 제도는 카탈루냐 법에 기반을 두고 있으며 우르젤 교구(스페인)의 일부입니다.[NEWLINE][NEWLINE]전통 경제는 양 사육에 기반을 두었으나 1950년대 이후 관광업의 중요성이 커져 21세기 초에는 안도라 경제의 중심이 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA', 					'카노사' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA_ADJ', 					'카노사의' UNION ALL
SELECT 'TXT_KEY_CIV5_CANOSSA_TEXT', 						'카노사는 이탈리아 레지오넬에밀리아 남서쪽에 있는 10세기 성터로, 1077년 교황 그레고리오 7세와 황제 하인리히 4세가 만난 장소로 유명합니다. 이 요새는 940년경 아토니 가문의 창시자이자 카노사의 첫 번째 백작인 아토 아달베르트가 건설했습니다.[NEWLINE]서임권 투쟁에서 교황권을 강력히 지지했던 카노사의 백작 부인 마틸다(토스카나의 마틸다)의 초청으로 그레고리오 7세는 1077년 그의 정적 하인리히 4세에 대항하기 위해 독일로 가는 길에 이 요새에 머물렀습니다. 폐위를 막기 위해 하인리히는 단순한 참회자의 모습으로 카노사로 여행했고, 1월 28일 3일간의 기다림 끝에 사면을 받았습니다.[NEWLINE][NEWLINE]이것이 교황권의 영구적인 승리를 의미하지는 않았지만, 카노사라는 이름은 세속 권력이 교회에 복종하는 것과 연관되었습니다. 따라서 독일에서 로마 가톨릭의 영향력에 대항한 프로이센의 문화 투쟁(Kulturkampf) 중 비스마르크는 "우리는 카노사로 가지 않을 것이다(Nach Canossa gehen wir nicht)"라는 격언을 남겼습니다.[NEWLINE][NEWLINE]성은 1255년 레지오 사람들에 의해 파괴되었습니다. 나중에 카노사 가문에 반환되었습니다. 1321년 지베르토 다 코레지오가 사망한 후 다시 레지오의 소유가 되었다가 1402년 시모네, 귀도, 알베르토 카노사가 되찾았습니다. 그러나 1409년 그들은 에스테 가문에 양도했고, 에스테 가문은 (1557년 파르마 공작 오타비오 파르네세의 짧은 기간을 제외하고) 1796년까지 보유했습니다. 1642년 모데나와 레지오의 공작 프란체스코 1세 데스테는 발렌티니 가문에 위탁했습니다. 후자는 1796년 치스파다나 공화국에 합류한 반항적인 지역 주민들에 의해 축출되었습니다. 1819년 발렌티니 가문에 반환된 후 1878년 이탈리아 국가가 성을 인수하여 국립 기념물로 지정했습니다.[NEWLINE][NEWLINE]"카노사"라는 지명은 1992년 인근 마을 치아노 덴자가 역사적, 문화적 유산을 기리기 위해 이름을 카노사로 변경하기 전까지는 폐허가 된 성과 인접한 작은 마을만을 지칭했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU', 						'베둘루' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU_ADJ', 						'발리의' UNION ALL
SELECT 'TXT_KEY_CIV5_BEDULU_TEXT', 							'"천 개의 사원이 있는 섬"으로 알려진 발리와 그 역사는 문화와 종교에 깊이 빠져 있으며, 인도네시아 힌두교의 마지막 보루 중 하나입니다.[NEWLINE][NEWLINE]발리는 기원전 2000년경 원래 동남아시아와 오세아니아에서 해양 동남아시아를 통해 이주한 오스트로네시아인들이 거주했습니다.[NEWLINE][NEWLINE]문화적으로나 언어적으로 발리인은 인도네시아 군도, 말레이시아, 필리핀, 오세아니아 사람들과 밀접한 관련이 있습니다. 이 시기의 석기 도구는 섬 서쪽의 체킥 마을 근처에서 발견되었습니다. 896년과 911년의 비문에는 왕에 대한 언급이 없다가 914년에 스리 케사리바르마가 언급됩니다. 또한 불교와 시바교가 동시에 행해지는 독특한 방언을 가진 독립적인 발리를 보여줍니다.[NEWLINE][NEWLINE]음푸 신독의 증손녀 마헨드라다타는 989년경 발리 왕 우다야나 와르마데와와 결혼하여 1001년경 아이를랑가를 낳았습니다. 이 결혼은 또한 발리에 더 많은 힌두교와 자바 문화를 가져왔습니다. 사칼렌두키라나 공주는 1098년에 등장했습니다. 수라디파는 1115년부터 1119년까지, 자야사크티는 1146년부터 1150년까지 통치했습니다. 자야팡구스는 1178년에서 1181년 사이의 비문에 등장하며, 아디쿤티케타나와 그의 아들 파라메스바라는 1204년에 등장합니다.[NEWLINE][NEWLINE]발리 문화는 서기 1세기경부터 인도, 중국, 특히 힌두 문화의 영향을 강하게 받았습니다. 발리 드위파("발리 섬")라는 이름은 914년 스리 케사리 와르마데와가 쓴 블란종 기둥 비문을 포함한 다양한 비문에서 발견되었으며 왈리드위파를 언급합니다. 이 시기에 사람들은 습지 경작에서 쌀을 재배하기 위해 현지에서 수박(subak)이라고 불리는 복잡한 관개 시스템을 개발했습니다. 오늘날에도 행해지는 일부 종교 및 문화적 전통은 이 시기로 거슬러 올라갈 수 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI', 						'양쥐미에' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI_ADJ', 						'대리국의' UNION ALL
SELECT 'TXT_KEY_CIV5_DALI_TEXT', 							'"위대한 진리" 또는 "위대한 통치"를 의미하는 대리국은 10세기부터 13세기까지 거의 3세기 동안 동남아시아에서 중요한 역할을 했던 불교 왕국이었습니다. 이곳은 신심의 왕국이자 많은 사원과 거대한 석탑의 왕국이었으며, 단일 민족이 아니라 많은 민족과 부족으로 구성되었으며 그중 가장 큰 부족은 백족과 이족이었습니다.[NEWLINE][NEWLINE]대리국은 불교를 보존하고 전파하는 데 영향력을 미친 것으로 유명합니다. 왕실 단씨 가문은 이전의 남조 선조들처럼 독실한 불교도였으며, 대리 주변과 석보산에 거대한 불교 사원을 건설했습니다. 이곳은 곧 불교 교육의 중심지가 되었습니다. 이곳의 왕들은 인근 동남아시아 왕국들의 불교 신왕 모델을 본받으려 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN', 						'물탄' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN_ADJ', 						'가즈나의' UNION ALL
SELECT 'TXT_KEY_CIV5_MULTAN_TEXT', 							'물탄은 파키스탄 펀자브주의 도시이자 물탄 지구의 주도입니다. 주의 남부에 위치하고 있으며 역사가 깊습니다. 인구는 380만 명이 넘으며(1998년 인구 조사 기준) 파키스탄에서 여섯 번째로 큰 도시입니다. 체나브강 바로 동쪽에 지어졌으며, 국토의 지리적 중심에 위치하고 카라치에서 약 966km 떨어져 있습니다.[NEWLINE][NEWLINE]물탄은 "피르와 성지의 도시"로 알려져 있으며 시장, 모스크, 훌륭하게 설계된 무덤이 있는 번영하는 도시입니다. 물탄 국제공항은 파키스탄의 주요 도시와 페르시아만의 도시로 항공편을 연결합니다. 도시의 산업에는 금속 가공, 제분, 설탕, 제유, 섬유 제조, 비료, 비누, 유리가 포함됩니다. 물탄은 또한 수공예품, 특히 도자기와 에나멜 작업으로 유명합니다.[NEWLINE][NEWLINE]아대륙에서 가장 오래된 도시 중 하나인 물탄은 이슬람 이전 시대의 성지인 태양신 사원의 우상에서 이름을 따왔습니다.[NEWLINE][NEWLINE]이 도시는 알렉산더 대왕에게 정복당했고(기원전 326년경), 중국 불교 학자 현장이 방문했으며(서기 641년), 아랍인들에게 점령당했고(8세기), 1005년 이슬람 튀르크 정복자 가즈나의 마흐무드와 1398년 티무르에게 점령당했습니다. 16세기와 17세기에 물탄은 무굴 황제의 통치하에 평화를 누렸습니다. 1818년 이 도시는 시크교 지도자 란지트 싱에게 점령당했습니다. 영국은 1848년부터 1947년 파키스탄이 독립할 때까지 이곳을 점령했습니다. 랜드마크로는 두 이슬람 성인의 14세기 무덤이 있는 오래된 요새가 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN', 						'파간' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN_ADJ', 						'버마의' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGAN_TEXT', 							'이 왕국은 최근 남조 왕국에서 이라와디 계곡으로 들어온 므란마/버마인들이 파간(오늘날의 바간)에 세운 9세기의 작은 정착지에서 성장했습니다. 이후 200년 동안 작은 공국은 점차 주변 지역을 흡수하여 성장하다가 1050년대와 1060년대에 아나우라타 왕이 파간 제국을 건국하여 처음으로 이라와디 계곡과 그 주변부를 하나의 정치체로 통일했습니다. 12세기 후반 아나우라타의 후계자들은 남쪽으로는 말레이반도 상부, 동쪽으로는 적어도 살윈강, 북쪽으로는 현재 중국 국경 아래, 서쪽으로는 아라칸 북부와 친 구릉지대까지 영향력을 확장했습니다. 12세기와 13세기에 파간은 크메르 제국과 함께 동남아시아 본토의 두 주요 제국 중 하나였습니다. 1280년대까지 면세 종교 재산의 지속적인 증가가 왕실의 신하와 군인들의 충성심을 유지하는 능력에 심각한 영향을 미치면서 왕국은 13세기 중반 쇠퇴하기 시작했습니다. 이는 아라칸인, 몬족, 몽골인, 샨족의 내부 혼란과 외부 도전의 악순환을 불러왔습니다. 반복된 몽골의 침략(1277-1301)으로 4세기 된 왕국은 1287년에 무너졌습니다. 붕괴 이후 250년 동안 정치적 분열이 이어져 16세기까지 지속되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH', 					'리시케시' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH_ADJ', 					'가르왈의' UNION ALL
SELECT 'TXT_KEY_CIV5_RISHIKESH_TEXT', 						'"가르왈 히말라야의 관문"이자 "세계 요가의 수도"로 알려진 리시케시(Hrishikesh라고도 표기)는 인도 우타라칸드주 데라둔 지구의 데라둔 근처에 있는 도시입니다. 갠지스강 우안에 위치하고 있으며 힌두교 순례지로서 고대 현자와 성인들이 더 높은 지식을 찾아 명상하던 곳입니다. 강변을 따라 수많은 사원과 아슈람이 지어져 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU', 					'무티줄루' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU_ADJ', 					'아난구의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUTITJULU_TEXT', 						'"아난구"는 서부 사막 언어를 사용하는 여러 호주 원주민 그룹을 설명하는 포괄적인 용어입니다. 이 용어는 피찬차차라족과 양쿤차차라족이 가장 두드러지게 사용합니다. 서부 사막 언어는 다른 어떤 원주민 언어보다 호주 영토의 더 많은 부분을 포괄하는 것으로 묘사되었습니다.[NEWLINE][NEWLINE]울룰루와 카타추타는 아난구 신앙 체계의 신성한 장소이며, 11개의 송라인이 그곳을 통과하거나 근처를 지나갑니다. 1979년 원주민 중앙 토지 위원회는 울룰루-카타추타 국립공원에 대한 소유권을 주장하기 위해 법적 투쟁을 시작했습니다. 1985년 결과적인 합의안이 시행되어 아난구에게 공원 관리 위원회의 과반수를 부여했지만 관광객의 공원 방문은 여전히 허용되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA', 					'이스칸와야' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA_ADJ', 					'칼라와야의' UNION ALL
SELECT 'TXT_KEY_CIV5_ISKANWAYA_TEXT', 						'이스칸와야는 볼리비아 라파스에서 북쪽으로 325km 떨어진 리카강 위 산등성이에 위치한 콜럼버스 이전의 신성한 장소입니다. 규모와 연대 면에서 이스칸와야는 페루의 마추픽추를 능가하지만 보존 상태는 좋지 않습니다. 이스칸와야 유적은 잉카 문명보다 앞선 몰로 문화로 거슬러 올라가며, 그 사람들은 기원전 800년경 또는 전성기인 1145년에서 1425년 사이에 건축물을 지은 것으로 추정됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU', 					'티와나쿠' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU_ADJ', 					'티와나쿠의' UNION ALL
SELECT 'TXT_KEY_CIV5_TIWANAKU_TEXT', 						'티와나쿠(스페인어: Tiahuanaco 및 Tiahuanacu)는 남아메리카 볼리비아 서부의 콜럼버스 이전 고고학 유적지입니다. 현재의 페루와 칠레까지 확장된 제국의 수도였으며 서기 300년부터 서기 1000년까지 번성했습니다. 티와나쿠는 안데스 학자들에게 잉카 제국 이전의 가장 중요한 문명 중 하나로 인정받고 있습니다. 약 500년 동안 주요 국가 권력의 의식 및 행정 수도였습니다. 고대 도시 국가의 유적은 라파스주 잉가비 지방 티와나쿠 자치구의 티티카카 호수 남동쪽 기슭 근처, 라파스에서 서쪽으로 약 72km(45마일) 떨어진 곳에 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO', 						'다노' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO_ADJ', 						'다가라의' UNION ALL
SELECT 'TXT_KEY_CIV5_DANO_TEXT', 							'다노는 부르키나파소 이오바주의 주도입니다. 직조와 도자기 시장이 있는 작은 마을이며, 식민지 기독교의 영향에도 불구하고 전통적인 우주론과 의식 관행을 지속해 온 다가라 사람들의 고향입니다. 이러한 관행에는 정령의 힘과 교감하고, 다른 세계의 존재를 불러내고, 개오지 조개껍데기로 점을 치는 것이 포함됩니다.[NEWLINE][NEWLINE]다가라 정착지는 부르키나파소 남서부의 약 3,500제곱킬로미터와 가나 북서부의 거의 같은 면적을 차지합니다. 다가라의 정치 및 사회 조직은 "텐간 시스템", 즉 다가라 공동체를 식별, 경계 설정 및 영적으로 보호하는 대지 성소 네트워크를 기반으로 합니다.[NEWLINE][NEWLINE]대지 성소는 희생 제사를 지내는 장소로, 주로 큰 나무 아래에 있는 돌로 구성되어 있으며, 규범에 따르면 해당 지역에 도착한 첫 번째 정착민이 세워야 합니다. 대지 성소에서는 여성과 토양의 비옥함, 특정 지역의 평화를 책임지는 대지의 신에게 제물을 바칩니다. 대지 성소에 대한 의식적 통제는 동시에 토지를 분배하고 필요한 희생 제물에 대한 기부를 요구할 권리를 의미합니다. 성소를 담당하는 제사장인 대지 사제는 나중에 온 정착민들에게 토지를 분배하고 다른 자원에 대한 접근을 규제하며, 때로는 상당히 많은 선물을 대가로 받기도 합니다. 늦게 온 사람들은 집을 짓고 죽은 자를 매장하기 위해서도 대지 사제의 허가를 받아야 합니다.[NEWLINE][NEWLINE]이 지역의 비중앙집권적 사회에서 텐간솝 또는 틴다나라고 불리는 대지 사제는 공동체 장로의 역할을 수행했으며, 식민지 이전 기간에는 유일한 지역 권위자였습니다. 전통에 따르면 대지 사제직은 정착지의 설립자나 같은 씨족 내의 후손에게 돌아갑니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES', 						'카리에스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES_ADJ', 						'아토스의' UNION ALL
SELECT 'TXT_KEY_CIV5_KARYES_TEXT', 							'아토스산의 수도원 공동체는 그리스의 동방 정교회 수도사 공동체로, 자치 지역의 지위와 분권화된 행정, 지역 및 지방 자치 단체의 권한을 결합하여 아토스산이 포함된 아토스 반도의 말단 부분을 영토로 하고 있습니다. 반도의 인접한 기부 부분은 중앙 마케도니아의 일반 아리스토텔리스 공동체에 속합니다.[NEWLINE][NEWLINE]조직적인 수도원 생활은 963년 성 아타나시우스 아토니테가 첫 번째 수도원을 세우면서 시작되었습니다. 1400년까지 40개의 수도원이 있었습니다. 오랫동안 그리스 정교회의 성산으로 여겨졌던 이곳은 1927년 신정 공화국으로 선포되었습니다. 아토스 수도원들은 잘 보존된 유물, 희귀 서적, 고대 문서 및 엄청난 역사적 가치를 지닌 예술품 컬렉션을 소장하고 있으며, 아토스산은 1988년부터 세계문화유산으로 등재되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY', 				'스강 과이' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY_ADJ', 				'하이다의' UNION ALL
SELECT 'TXT_KEY_CIV5_SGANG_GWAAY_TEXT', 					'북미의 많은 원주민 부족 중 하이다족은 섬사람으로서 독특합니다. 틀링깃족 및 침시안족과 관련된 하이다 사회는 귀족, 평민, 노예의 계급으로 나뉜 씨족 시스템을 중심으로 조직되었습니다. 모계 혈통을 통해 결정되는 두 개의 주요 씨족이 있었습니다. 이 씨족들은 다시 혈통으로 세분화되었습니다.[NEWLINE][NEWLINE]하이다족은 특히 목공, 직조, 항해에 재능이 있습니다. 그들은 토템 폴을 처음 사용한 것으로 알려져 있습니다. 그들의 해양 활동은 식민지 개척자들과 많은 평화로운 무역로를 개척하게 했지만, 지역적으로는 노예제를 시행하는 두려운 전사들이었습니다. 이러한 이유로 그들은 종종 "북미의 바이킹"이라고 불렸습니다.[NEWLINE][NEWLINE]오늘날 하이다 과이 본섬의 하이다 보호구역은 하이다 국가 위원회를 만들기 위해 뭉쳤습니다. 그들은 문화적 부흥을 경험하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ', 				'냐르야나 마르크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ_ADJ', 				'네네츠의' UNION ALL
SELECT 'TXT_KEY_CIV5_NYARYANA_MARQ_TEXT', 					'사모예드라고도 알려진 네네츠인은 러시아 북부 북극 지방의 원주민입니다. 2010년 최신 인구 조사에 따르면 러시아 연방에는 44,857명의 네네츠인이 있으며, 대부분 야말로-네네츠 자치구와 네네츠 자치구에 거주하고 있습니다. 그들은 툰드라 또는 숲 종류의 네네츠어를 사용합니다. 러시아어의 문자 그대로의 형태소 samo와 yed는 "자기 식인종"이라는 의미를 전달하여 경멸적으로 보입니다. 따라서 사모예드라는 이름은 20세기 들어 빠르게 사용되지 않게 되었고, 사람들은 "사람"을 의미하는 네네츠라는 이름을 사용합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE', 						'아데헤' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE_ADJ', 						'관체의' UNION ALL
SELECT 'TXT_KEY_CIV5_ADEJE_TEXT', 							'관체족은 북아프리카 해안에서 서쪽으로 약 100km(60마일) 떨어진 대서양 카나리아 제도의 원주민이었습니다. 그들은 17세기에 멸종된 관체어를 사용했는데, 이는 베르베르어와 관련이 있는 것으로 여겨집니다. 그들은 기원전 1천 년경에 군도에 도착했을 것으로 추정됩니다.[NEWLINE][NEWLINE]관체족은 유럽인이 도착하기 전에 마카로네시아 군도 지역에 살았던 것으로 알려진 유일한 원주민이었습니다. 다른 마카로네시아 군도(카보베르데 제도, 마데이라, 아조레스 제도)에 사람이 살았다는 인정된 증거는 없습니다. 15세기 초부터 시작된 스페인의 카나리아 정복 이후 많은 원주민이 스페인 정복자들에 의해 전멸했고 나머지는 시간이 지남에 따라 정착민 인구와 문화에 동화되었지만, 라고메라섬의 휘파람 언어인 실보와 카나리아 스페인어의 일부 어휘와 같이 카나리아 관습과 전통 내에 원래 문화의 요소가 남아 있습니다.[NEWLINE][NEWLINE]일부 학자들은 관체족과 문화의 파괴를 식민지 대량 학살의 초기 사례로 분류했습니다. 2017년 관체족의 첫 번째 게놈 전체 데이터는 북아프리카 기원을 확인했으며 인근 북아프리카 본토의 고대 북아프리카 베르베르인과 유전적으로 가장 유사하다는 것을 확인했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE', 				'우테이-니치에' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE_ADJ', 				'아라파호의' UNION ALL
SELECT 'TXT_KEY_CIV5_WOOTEI_NIICIE_TEXT', 					'약 3,000년 전, 아라파호어를 사용하는 조상인 헤테이노노에이노는 오늘날 캐나다 매니토바와 미국 미네소타로 분류되는 레드강 계곡을 따라 서부 오대호 지역에 살았습니다. 그곳에서 아라파호족은 옥수수를 포함한 작물을 재배하는 농경 민족이었습니다.[NEWLINE][NEWLINE]캐나다 동부의 유럽 식민지화 이후, 초기 샤이엔족인 히테시노와 함께 아라파호족은 오지브와족에 의해 서쪽 대평원으로 강제 이주당했습니다. 그들은 프랑스 무역 동맹국으로부터 총을 얻어 수가 많고 강력했습니다. 아라파호족의 조상은 1700년 이전에 서부 오대호 지역에서 대평원으로 들어왔습니다. 평원에서의 초기 역사 동안 아라파호족은 캐나다의 사우스 서스캐처원강에서 남쪽으로 몬타나, 와이오밍, 사우스다코타 서부에 이르는 북부 평원에 살았습니다.[NEWLINE][NEWLINE]아라파호족이 말을 얻기 전에는 개를 짐 싣는 동물로 사용하여 트라보아를 끌었습니다. 아라파호족은 1700년대 초 다른 부족으로부터 말을 얻었고, 이는 그들의 생활 방식을 바꾸어 놓았습니다. 그들은 말을 짐 싣는 동물과 타는 동물로 사용하는 유목민이 되었습니다. 그들은 더 많은 짐을 운반하고 말을 타고 더 쉽게 이동하여 더 쉽고 넓게 사냥할 수 있었고 평원에서의 사냥 성공률을 높였습니다. 점차 아라파호족은 더 남쪽으로 이동하여 밀접하게 동맹을 맺은 북부 및 남부 아라파호족으로 나뉘었고 몬타나 남부, 와이오밍 대부분, 네브래스카 팬핸들, 콜로라도 중부 및 동부, 오클라호마 서부, 캔자스 극서부의 땅에 걸친 넓은 공동 영토를 확립했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR', 						'다카르' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR_ADJ', 						'아달의' UNION ALL
SELECT 'TXT_KEY_CIV5_DAKKAR_TEXT', 							'다카르 또는 데케르라고도 알려진 다카르는 현재 에티오피아 동부에 위치한 역사적인 이슬람 도시였습니다. 1415년부터 1422년까지 통치한 사브르 아드 딘 3세가 15세기 초에 아달 술탄국(1415–1577)을 건국한 후 첫 번째 수도 역할을 했습니다. 아달 술탄국은 현재의 에티오피아 동부, 지부티, 소말리아 북부를 중심으로 아프리카의 뿔에서 번성했던 강력한 중세 이슬람 국가였습니다. 술탄국은 홍해와 인도양 무역에서 핵심적인 역할을 하여 아프리카와 아라비아, 아시아를 연결했습니다. 16세기 초 아흐마드 "그란"으로도 알려진 군사령관 아흐마드 이븐 이브라힘 알가지가 이끈 에티오피아 제국과의 치열한 갈등으로 가장 유명합니다. 그의 원정은 1543년 패배하고 사망하기 전까지 에티오피아 왕국을 거의 무너뜨릴 뻔했습니다. 술탄국은 결국 내부 및 외부의 압력으로 쇠퇴했지만, 이 지역의 정치, 문화, 종교적 지형에 지속적인 유산을 남겼습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA', 					'호니아라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA_ADJ', 					'솔로몬의' UNION ALL
SELECT 'TXT_KEY_CIV5_HONIARA_TEXT', 						'호니아라는 과달카날 북서쪽 해안에 위치한 솔로몬 제도의 수도이자 가장 큰 도시입니다. 이 지역은 제2차 세계 대전 중 연합군과 일본군 사이의 치열한 전투, 특히 과달카날 전역(1942–1943)의 현장으로 세계적인 주목을 받았습니다. 전쟁 후 호니아라는 더 나은 인프라와 전략적 위치 때문에 툴라기를 대신할 국가 수도로 선정되었습니다. 1952년 공식적으로 수도로 지정된 이 도시는 빠르게 발전하여 국가의 행정, 경제, 문화 중심지가 되었습니다. 오늘날 호니아라에는 정부 기관, 분주한 항구, 다양한 인구가 거주하고 있으며 기념비와 유물과 같은 전쟁의 잔재가 여전히 눈에 띄어 현대적 정체성을 중추적인 전시 과거와 연결합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA', 					'카라스요크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA_ADJ', 					'사미의' UNION ALL
SELECT 'TXT_KEY_CIV5_KARASJOHKA_TEXT', 						'사미족은 노르웨이, 스웨덴, 핀란드 북부 지역과 러시아 콜라반도, 즉 사프미라고 알려진 문화 지역의 원주민입니다. 수천 년 전으로 거슬러 올라가는 역사를 가진 사미족은 전통적으로 반유목 순록 목축, 낚시, 사냥을 하며 북극 환경과 밀접한 관계를 유지하며 살았습니다. 그들의 문화는 구전 전통, 수공예품(두오지), 각티와 같은 독특한 의복이 풍부합니다. 19세기 이후 그들은 국가 정부의 동화 압력과 토지 권리 상실에 직면했습니다. 그러나 최근 수십 년 동안 사미 의회 설립과 권리 인정 강화로 강력한 문화적, 정치적 부흥이 있었습니다. 오늘날 사미족은 언어, 전통, 조상의 땅을 보존하면서 현대 생활과의 균형을 계속 유지하고 있습니다.' UNION ALL
