SELECT 'TXT_KEY_CSTRAIT_MINOR_CIV_THIMPHU', 			'[COLOR_MAGENTA]드룩 첸덴:[ENDCOLOR] [COLOR_CYAN]언덕[ENDCOLOR] 위의 도시는 +3 [ICON_CULTURE] 문화를 얻습니다. 도시는 턴당 10 [ICON_CULTURE] 문화마다 1 [ICON_STRENGTH] 방어력을 얻습니다.[NEWLINE]' UNION ALL
SELECT 'TXT_KEY_CSTRAIT_MINOR_CIV_TIWANAKU', 			'[COLOR_MAGENTA]하나 파차:[ENDCOLOR] 플레이어는 [ICON_PEACE] 신앙으로 [COLOR_YIELD_GOLD]시스케노[ENDCOLOR] 유닛(고유 [COLOR_YIELD_GOLD]선교사[ENDCOLOR])을 구매할 수 있습니다. 플레이어는 [ICON_MISSIONARY] [COLOR_YIELD_GOLD]선교사[ENDCOLOR]를 소모하여 [COLOR_CITY_BLUE]평원[ENDCOLOR], [COLOR_CITY_BLUE]툰드라[ENDCOLOR] 또는 [COLOR_CITY_BLUE]사막[ENDCOLOR]이 있는 평지에 [COLOR_CITY_BROWN]가라앉은 안뜰[ENDCOLOR] 시설(인접 불가)을 건설할 수 있습니다 ([ICON_RESEARCH], [ICON_CULTURE], [ICON_PEACE], [ICON_TOURISM]).[NEWLINE]' UNION ALL
SELECT 'TXT_KEY_CSTRAIT_MINOR_CIV_TUNIS', 				'[COLOR_MAGENTA]카르타고의 칼리프:[ENDCOLOR] 플레이어는 [COLOR_CITY_BLUE]사막[ENDCOLOR]에 [COLOR_CITY_BROWN]리바트[ENDCOLOR] 시설을 건설할 수 있습니다 ([ICON_GOLD], [ICON_CULTURE], [ICON_PEACE], [ICON_GREAT_GENERAL]).[NEWLINE]' UNION ALL
SELECT 'TXT_KEY_CSTRAIT_MINOR_CIV_TYRE', 				'[COLOR_MAGENTA]고대 세계의 유적:[ENDCOLOR] [ICON_ARTIFACT] [COLOR_CITY_BROWN]랜드마크[ENDCOLOR]는 +2 [ICON_GOLD] 금을 얻습니다. 도시는 [ICON_ARTIFACT] [COLOR_YIELD_GOLD]고고학자[ENDCOLOR]에 대해 +10% 생산력을 얻습니다. [ICON_WONDER] 세계 불가사의 건설 시 시대와 해당 도시의 [ICON_WONDER] 세계 불가사의 수에 비례하여 20-40 [ICON_TOURISM] 관광을 얻습니다.[NEWLINE]' UNION ALL
