-- units
SELECT 'TXT_KEY_UNIT_SWISS_GUARD', 						'스위스 근위대' UNION ALL
SELECT 'TXT_KEY_UNIT_SWISS_GUARD_HELP', 					'고유 [COLOR_YIELD_GOLD]용병 유닛[ENDCOLOR][NEWLINE]----------------[NEWLINE]이 유닛은 [ICON_GOLD] 금 또는 [ICON_PEACE] 신앙으로만 구매할 수 있습니다 ([COLOR:200:200:200:255]바티칸 시국[ENDCOLOR]의 능력 접근 필요)' UNION ALL
SELECT 'TXT_KEY_UNIT_SWISS_GUARD_STRATEGY', 				'스위스 근위대는 바티칸 시국의 고유 용병 유닛으로, 기술 계통도에서 [COLOR_POSITIVE_TEXT]자유 용병대[ENDCOLOR]와 [COLOR_POSITIVE_TEXT]외인부대[ENDCOLOR] 사이에 위치합니다. ([ICON_GOLD] 금 또는 [ICON_PEACE] 신앙으로) 구매만 가능하며 구매 후 이동할 수 있습니다. 그렇게 하는 데 정책이 필요하지 않습니다. 스위스 근위대는 시대가 지날 때마다 추가 [ICON_STRENGTH] 전투력을 얻으며, 소유한 도시(소량), 수도(더 많이) 또는 성도(가장 많이) 근처에서 적 유닛을 처치하면 회복합니다. 또한 발견된 기술([COLOR_CYAN]라디오[ENDCOLOR] 및 [COLOR_CYAN]통신[ENDCOLOR])에 따라 산출량을 생성합니다. 이 유닛은 구식이 되지 않습니다.' UNION ALL
SELECT 'TXT_KEY_CIV5_UNIT_SWISS_GUARD', 					'스위스 근위대는 역사적으로 중세와 르네상스 시대에 유럽 전역의 궁정에서 경호원으로 복무하고자 했던 스위스 출신 용병들을 묘사합니다. 변함없는 충성심과 용맹함으로 칭송받은 스위스 근위대는 의장대에서 최전선 부대에 이르기까지 다양한 기능을 수행했으며 프랑스, 스페인, 나폴리를 포함한 유럽의 가장 위대한 강대국 군대에서 사용되었습니다. 1874년 스위스 헌법에 의해 외세의 스위스 근위대 모집이 금지되었지만, 교황청에 봉사하는 교황청 스위스 근위대는 예외였으며 오늘날에도 교황의 안전과 사도 궁전의 보안을 책임지는 바티칸의 주요 병력으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_UNIT_GURKHA', 							'구르카' UNION ALL
SELECT 'TXT_KEY_UNIT_GURKHA_HELP', 							'고유 [COLOR_YIELD_GOLD]퓨질리어[ENDCOLOR][NEWLINE]----------------[NEWLINE]이 유닛은 훈련하거나 구매할 수 있습니다 ([COLOR:200:200:200:255]카트만두[ENDCOLOR]의 능력 접근 필요)' UNION ALL
SELECT 'TXT_KEY_UNIT_GURKHA_STRATEGY', 						'구르카는 카트만두의 퓨질리어 대체 유닛입니다. 퓨질리어보다 일찍 잠금 해제되는 것 외에도 구르카는 전투에서 더 많은 경험치를 얻으며 막힌 적 유닛에 대해 큰 이점을 가집니다.' UNION ALL
SELECT 'TXT_KEY_CIV5_UNIT_GURKHA', 							'구르카는 산악 지대인 네팔과 인도의 고르카랜드 지역 원주민입니다. 용맹함, 두려움 없음, 죽음을 무시하는 태도로 유명한 그들은 1814년 동인도 회사가 네팔을 상대로 벌인 구르카 전쟁 초기에 영국군 지휘관들에게 깊은 인상을 남겼습니다. 1815년 전쟁이 끝나기도 전에 영국 인도군 내에 첫 번째 구르카 연대가 창설되었습니다. 19세기와 20세기 내내 구르카는 전쟁과 수많은 인도 반란에도 불구하고 영국 왕실에 충성을 다했습니다. 그들은 두 차례의 세계 대전에서 영국군의 일원으로 싸웠으며 15개의 소총 연대를 구성했습니다. 그들은 어떤 고난도 견뎌내는 능력으로 널리 존경받았으며 치명적인 쿠크리 칼 솜씨로 두려움의 대상이 되었습니다. 구르카 연대는 오늘날까지 복무하고 있습니다.' UNION ALL
