SELECT 'TXT_KEY_RESOURCE_BEER_TEXT',					'맥주는 세계에서 가장 오래되고 가장 널리 소비되는 알코올음료 중 하나입니다. 또한 물과 차 다음으로 전반적으로 세 번째로 인기 있는 음료입니다. 맥주는 곡물, 가장 일반적으로 맥아 보리로 양조되지만 밀, 옥수수, 쌀도 사용됩니다. 양조 과정에서 맥아즙의 전분 당이 발효되어 결과 맥주에 에탄올과 탄산이 생성됩니다.' UNION ALL
SELECT 'TXT_KEY_RESOURCE_BEER_MONOPOLY',				'[COLOR_POSITIVE_TEXT]독점 보너스:[ENDCOLOR] 모든 소유 도시에서 +10% [ICON_GREAT_ENGINEER] 위대한 기술자 점수.' UNION ALL
SELECT 'TXT_KEY_RESOURCE_CHEESE',						'치즈' UNION ALL
SELECT 'TXT_KEY_RESOURCE_CHEESE_TEXT',					'치즈는 우유 단백질 카제인을 응고시켜 다양한 맛, 질감, 형태로 생산되는 우유 유래 유제품입니다. 다양한 국가에서 천 가지 이상의 치즈가 생산됩니다. 그 스타일, 질감 및 풍미는 우유의 원산지(동물의 식단 포함), 저온 살균 여부, 유지방 함량, 박테리아 및 곰팡이, 가공 및 숙성에 따라 달라집니다. 치즈는 휴대성, 긴 수명, 높은 지방, 단백질, 칼슘 및 인 함량으로 인해 가치가 있습니다.' UNION ALL
SELECT 'TXT_KEY_RESOURCE_CHEESE_MONOPOLY',				'[COLOR_POSITIVE_TEXT]독점 보너스:[ENDCOLOR] 모든 [ICON_RES_COW] [COLOR_GREY]소[ENDCOLOR] 및 [ICON_RES_SHEEP] [COLOR_GREY]양[ENDCOLOR]에서 +2 [ICON_PRODUCTION].' UNION ALL
SELECT 'TXT_KEY_RESOURCE_HONEY',						'꿀' UNION ALL
SELECT 'TXT_KEY_RESOURCE_HONEY_TEXT',					'꿀은 꿀벌과 일부 관련 곤충이 만드는 달콤하고 점성이 있는 식품 물질입니다. 꿀벌은 식물의 당분 분비물(꽃 꿀)이나 다른 곤충의 분비물(감로 등)로부터 역류, 효소 활동 및 수분 증발을 통해 꿀을 생산합니다. 꿀벌은 벌집이라고 불리는 왁스 구조에 꿀을 저장합니다. 꿀의 사용과 생산은 고대 활동으로서 길고 다양한 역사를 가지고 있습니다. 스페인 쿠에바스 데 라 아라냐의 여러 동굴 벽화는 적어도 8,000년 전에 꿀을 채집하는 인간을 묘사합니다.' UNION ALL
