SELECT 'TXT_KEY_RESOURCE_MANUSCRIPTS',					'필사본' UNION ALL
SELECT 'TXT_KEY_RESOURCE_MANUSCRIPTS_TEXT',				'필사본 또는 수고본은 인쇄되거나 다른 방식으로 복제되는 것이 아니라 손으로 쓴 편지와 같이 한 명 이상의 사람이 수동으로 만든 서면 정보입니다. 이 용어는 글쓰기 이외의 다른 방식으로 손으로 기록된 정보, 예를 들어 단단한 재료에 새겨진 비문이나 석고에 칼끝으로 긁거나(낙서의 원래 의미) 왁스 판에 스타일러스로 긁은 것(로마인이 메모하는 방식), 또는 굽지 않은 점토 평판에 뾰족한 스타일러스로 찍은 쐐기 문자와 같은 정보에도 사용될 수 있습니다.' UNION ALL
