-- world wonders
SELECT 'TXT_KEY_BUILDING_POTALA', 						'포탈라궁' UNION ALL
SELECT 'TXT_KEY_BUILDING_POTALA_QUOTE', 				'[NEWLINE]"포탈라궁 옥상에 처음 발을 디뎠을 때, 나는 전에도 후에도 느껴보지 못한 감정을 느꼈다. 마치 내 존재의 옥상에 발을 디디는 것 같았고, 이전에 방문한 적 없는 의식의 차원에 들어서는 것 같았다."[NEWLINE] - 피코 아이이어[NEWLINE]' UNION ALL
SELECT 'TXT_KEY_BUILDING_POTALA_PEDIA', 				'티베트 라사에 위치한 포탈라궁은 아시아에서 가장 유명한 건축 및 문화 기념물 중 하나입니다. 그 기원은 송첸 감포 왕이 처음 요새를 지은 7세기로 거슬러 올라가지만, 오늘날 볼 수 있는 웅장한 궁전은 주로 17세기 제5대 달라이 라마의 지도하에 건설되었습니다. 해발 3,700미터(12,100피트)의 붉은 산(마르포리) 정상에 지어진 이 궁전은 수 세기 동안 티베트의 정치 및 영적 생활의 중심지였습니다. 이곳은 역대 달라이 라마의 겨울 거주지이자 20세기 중반 중국 행정부가 티베트에 수립될 때까지 티베트 통치의 중심지 역할을 했습니다. 1994년 유네스코 세계문화유산으로 지정된 이 궁전은 티베트 불교의 역사적 권위와 이 지역의 복잡한 정치사를 모두 구현하고 있습니다.[NEWLINE][NEWLINE]건축학적으로 포탈라궁은 요새와 같은 견고함과 화려한 종교적 디자인이 조화를 이룬 놀라운 위업입니다. 13층 높이로 솟아 있으며 1,000개 이상의 방, 예배당, 사원을 포함하는 이 궁전은 크게 두 부분으로 나뉩니다. 행정 사무실과 거주 공간이 있는 백궁과 종교 연구, 기도, 달라이 라마의 정교한 무덤이 있는 홍궁입니다. 벽은 불교 우주론, 역사, 가르침을 묘사한 벽화로 장식되어 있으며, 보물창고에는 엄청난 문화적 가치를 지닌 수많은 유물, 경전, 불상이 보관되어 있습니다. 웅장함을 넘어 이 궁전은 티베트의 정체성과 영성의 상징으로 남아 있으며, 라사 계곡 위로 솟은 위엄 있는 실루엣으로 순례자, 역사가, 관광객 모두를 끌어들이고 있습니다.' UNION ALL
SELECT 'TXT_KEY_BUILDING_POTALA_HELP', 					'[COLOR_CYAN]라사[ENDCOLOR]의 능력 접근 및 [COLOR_POSITIVE_TEXT]세계 의회[ENDCOLOR]의 활성 회기가 필요합니다.[NEWLINE]----------------[NEWLINE][COLOR:200:200:200:255]라사[ENDCOLOR]에 대한 [COLOR_YIELD_GOLD]세력권[ENDCOLOR]을 발동합니다.';
