SELECT		'TXT_KEY_RESOURCE_GLASS_MONOPOLY',			'[COLOR_POSITIVE_TEXT]독점 보너스:[ENDCOLOR] 현재 적용된 각 행복 또는 고정 산출량 [ICON_MONOPOLY] 전역 독점 보정치는 추가로 +1 보너스를 얻으며, 퍼센트 기반 [ICON_MONOPOLY] 전역 독점 보정치는 추가로 +1% 보너스를 얻습니다.' UNION ALL
SELECT		'TXT_KEY_RESOURCE_JEWELRY_MONOPOLY',		'[COLOR_POSITIVE_TEXT]독점 보너스:[ENDCOLOR] 모든 소유 도시에서 +10% [ICON_GREAT_MERCHANT] 위대한 상인 점수.' UNION ALL
SELECT		'TXT_KEY_RESOURCE_PORCELAIN_MONOPOLY',		'[COLOR_POSITIVE_TEXT]독점 보너스:[ENDCOLOR] 모든 소유 도시에서 [COLOR_YIELD_GOLD]고고학자 유닛[ENDCOLOR]에 대해 +15% [ICON_PRODUCTION] 생산력.';
