UPDATE Language_ko_KR SET Text = Text||'[NEWLINE][NEWLINE]근처 [ICON_RES_DOGO_CANARIO]: +2 [ICON_PRODUCTION] 생산력.' WHERE Tag = 'TXT_KEY_BUILDING_AGRIBUSINESS_HELP';
UPDATE Language_ko_KR SET Text = Text||'[NEWLINE][NEWLINE]근처 [ICON_RES_REINDEER]: +2 [ICON_FOOD] 식량.' WHERE Tag = 'TXT_KEY_BUILDING_STABLE_HELP';
