/* More Wonders (Potala Palace)*/
INSERT INTO Language_ko_KR (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_POTALA_FOR_MW_HELP_CUT', '웅장한 [COLOR_YIELD_FOOD]포탈라궁[ENDCOLOR]은 달라이 라마의 거주지이며(+3[ICON_CULTURE]; +10%[ICON_CULTURE]; +10%[ICON_PEACE]; [COLOR_CYAN]라사[ENDCOLOR]와 동맹이 아닐 경우 보정치는 [COLOR_NEGATIVE_TEXT]반감[ENDCOLOR]됨) 놀랍게도 거대한 주거용 건물 역할도 합니다(-2[ICON_HAPPINESS_3] 고통). 이것은 당신의 제국을 작고 평화로운 국가와 강력하게 연결합니다([COLOR_CYAN]라사[ENDCOLOR]에 대한 [COLOR_YIELD_GOLD]세력권[ENDCOLOR]). 달라이 라마의 목소리는 망명 후에도 침묵하지 않으며 여전히 폭력 없이 갈등을 해결하려고 노력합니다(+1[ICON_DIPLOMAT] 연맹 투표).';
	
INSERT INTO Language_ko_KR (Tag, Text)
SELECT 'TXT_KEY_BUILDING_POTALA_FOR_MW_HELP', '모든 요구 사항(lua 포함):[NEWLINE][ICON_BULLET]특수: [COLOR:200:200:200:255]라사의 능력[ENDCOLOR], [COLOR:45:150:50:255]세계 의회[ENDCOLOR][NEWLINE]----------------[NEWLINE][COLOR:200:200:200:255]라사[ENDCOLOR]에 대한 [COLOR_YIELD_GOLD]세력권[ENDCOLOR]을 발동합니다.[NEWLINE]----------------[NEWLINE][ICON_CITY_STATE] [COLOR:200:200:200:255]도시 국가[ENDCOLOR]의 추가 보너스:[NEWLINE][ICON_BULLET][COLOR:200:200:200:255]라사[ENDCOLOR]: +5% [ICON_CULTURE] 및 +5% [ICON_PEACE]';
